CREATE TRIGGER memory_derivation_asset_content_expiry AFTER INSERT ON memory_derivation_asset_edges
WHEN NEW.target_kind='content'
BEGIN
 UPDATE private_content SET expires_at=MIN(expires_at,NEW.expires_at) WHERE content_id=NEW.target_id;
 UPDATE private_content_retention_scopes SET assigned_expires_at=MIN(assigned_expires_at,NEW.expires_at) WHERE content_id=NEW.target_id;
END

CREATE TRIGGER memory_derivation_consumer_content_expiry AFTER INSERT ON memory_derivation_consumer_contents
BEGIN UPDATE private_content SET expires_at=MIN(expires_at,(SELECT expires_at FROM memory_derivation_consumers WHERE origin_id=NEW.origin_id)) WHERE content_id=NEW.content_id;
 UPDATE private_content_retention_scopes SET assigned_expires_at=MIN(assigned_expires_at,(SELECT expires_at FROM memory_derivation_consumers WHERE origin_id=NEW.origin_id)) WHERE content_id=NEW.content_id; END

CREATE TRIGGER memory_derivation_split_apply AFTER INSERT ON memory_derivation_split_commands
BEGIN
 DELETE FROM memory_derivation_jobs WHERE job_id=NEW.parent_job_id;
 INSERT INTO memory_derivation_jobs(job_id,consent_id,purpose,after_sequence,through_sequence,source_count,created_at,expires_at,state,lease_token,lease_expires_at,attempts,not_before,failure_code)
 VALUES(NEW.left_job_id,json_extract(NEW.parent_json,'$[1]'),json_extract(NEW.parent_json,'$[2]'),json_extract(NEW.parent_json,'$[3]'),NEW.split_sequence,CAST(json_extract(NEW.parent_json,'$[5]')/2 AS INTEGER),json_extract(NEW.parent_json,'$[6]'),json_extract(NEW.parent_json,'$[7]'),'waiting',NULL,NULL,0,json_extract(NEW.parent_json,'$[6]'),NULL);
 INSERT INTO memory_derivation_jobs(job_id,consent_id,purpose,after_sequence,through_sequence,source_count,created_at,expires_at,state,lease_token,lease_expires_at,attempts,not_before,failure_code)
 VALUES(NEW.right_job_id,json_extract(NEW.parent_json,'$[1]'),json_extract(NEW.parent_json,'$[2]'),NEW.split_sequence,json_extract(NEW.parent_json,'$[4]'),json_extract(NEW.parent_json,'$[5]')-CAST(json_extract(NEW.parent_json,'$[5]')/2 AS INTEGER),json_extract(NEW.parent_json,'$[6]'),json_extract(NEW.parent_json,'$[7]'),'waiting',NULL,NULL,0,json_extract(NEW.parent_json,'$[6]'),NULL);
 INSERT INTO memory_derivation_job_sources(job_id,enrollment_id,event_id,sequence,expires_at)
 SELECT CASE WHEN json_extract(value,'$[3]')<=NEW.split_sequence THEN NEW.left_job_id ELSE NEW.right_job_id END,json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]') FROM json_each(NEW.references_json);
 DELETE FROM memory_derivation_split_commands WHERE parent_job_id=NEW.parent_job_id;
END

CREATE TRIGGER organization_project_nesting_local_delete AFTER DELETE ON project_containment BEGIN
 UPDATE memory_derivation_contexts SET state='dismissed' WHERE state='accepted' AND source_enrollment_id<>target_enrollment_id AND source_enrollment_id IN(SELECT enrollment_id FROM memory_live_enrollments WHERE organization_id=OLD.organization_id);
END

CREATE TRIGGER organization_project_nesting_migration_delete AFTER DELETE ON project_migration_states BEGIN
 DELETE FROM organization_project_nesting WHERE organization_id=OLD.organization_id;
END

CREATE TRIGGER project_containment_compensation AFTER INSERT ON events WHEN NEW.compensates_event_id IS NOT NULL BEGIN
 DELETE FROM project_containment WHERE declaration_ref=NEW.compensates_event_id OR parent_declaration_ref=NEW.compensates_event_id;
END

